create table if not exists public.jkg_mail_messages (message_id text primary key, thread_id text not null default '', from_address text not null default '', from_name text not null default '', subject text not null default '', snippet text not null default '', body_text text not null default '', received_at timestamptz, attachments jsonb not null default '[]'::jsonb, category text not null default 'General Communication', priority text not null default 'Normal', requires_action boolean not null default false, summary text not null default '', requested_actions jsonb not null default '[]'::jsonb, facts jsonb not null default '{}'::jsonb, processing_status text not null default 'Processed', case_status text not null default 'New', assigned_to text, reviewer text, proposed_due date, confirmed_due date, hearing_date date, verified boolean not null default false, draft jsonb not null default '{}'::jsonb, activity jsonb not null default '[]'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists jkg_mail_received_idx on public.jkg_mail_messages(received_at desc);
create table if not exists public.jkg_mail_sync_state (id smallint primary key default 1 check(id=1), mailbox text not null default '', connected boolean not null default false, backfill_completed boolean not null default false, messages_processed bigint not null default 0, last_sync_at timestamptz, worker_seen_at timestamptz, last_error text not null default '', updated_at timestamptz not null default now());
insert into public.jkg_mail_sync_state(id) values(1) on conflict(id) do nothing;
alter table public.jkg_mail_messages enable row level security;
alter table public.jkg_mail_sync_state enable row level security;
revoke all on public.jkg_mail_messages from anon, authenticated, public;
revoke all on public.jkg_mail_sync_state from anon, authenticated, public;